var configUpdated = false;
var alarmConfig = JSON.parse(metadata.ss_alarmConfig);

if (alarmConfig.locationThresholds == null) {
    return returnMsg(alarmConfig, configUpdated);
}

var thresholdsToRemove = [];
foreach(threshold: alarmConfig.locationThresholds) {
    if (threshold.eventType.contains("Zone")) {
        threshold.zones = removeZoneIfPresent(threshold.zones);
    } else if (threshold.eventType.contains("Geofence")) {
        if (threshold.zones.id.id == msg.id.id) {
            thresholdsToRemove.push(threshold);
            configUpdated = true;
        } else {
            threshold.geofences = removeGeofenceIfPresent(threshold.geofences);
        }

    }

    if (threshold.zones.isEmpty() || (threshold
            .eventType.contains("Geofence") && threshold
            .geofences.isEmpty())) {
        thresholdsToRemove.push(threshold);
    }
}


foreach(remove: thresholdsToRemove) {
    alarmConfig.locationThresholds.remove(remove);
}

return returnMsg(alarmConfig, configUpdated);


function removeGeofenceIfPresent(geofences) {
    var updatedGeofences = [];
    foreach(geofence: geofences) {
        if (geofence.id.id != msg.id.id) {
            updatedGeofences.push(geofence);
            configUpdated = true;
        }
    }
    return updatedGeofences;
}

function removeZoneIfPresent(zones) {
    var updatedZones = [];
    foreach(zone: zones) {
        if (zone.id.id != msg.id.id) {
            updatedZones.push(zone);
            configUpdated = true;
        }
    }
    configUpdated = true;
    return updatedZones;
}

function returnMsg(alarmConfig, configUpdated) {
    return {
        msg: {
            alarmConfig: alarmConfig
        },
        metadata: {
            configUpdated: configUpdated
        },
        msgType: "POST_ATTRIBUTES_REQUEST"
    };
}
